def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)
    b = bearing_to(enemy.x, enemy.y)
    tr = b * 3.0
    if tr > 250.0:
        tr = 250.0
    elif tr < -250.0:
        tr = -250.0
    diff = (tr - me.turn_rate) * 0.04
    if diff > 1.5:
        diff = 1.5
    elif diff < -1.5:
        diff = -1.5
    a = abs(b)
    f = 1.0
    if a > 30.0:
        f = 0.6
    if a > 70.0:
        f = 0.0
    if a > 120.0:
        f = -0.5
    l = f - diff
    r = f + diff
    if l > 1.0:
        l = 1.0
    elif l < -1.0:
        l = -1.0
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    return (l, r)


