def drive(me, enemy, arena):
    # Angle to enemy (-180..180, left positive)
    ang = bearing_to(enemy.x, enemy.y)
    # Distance to enemy
    dist = distance_to(enemy.x, enemy.y)

    # Desired forward speed: fast when far, slower when close
    if dist > 2.5:
        base = 1.0
    elif dist > 1.0:
        base = 0.7
    else:
        base = 0.4

    # Proportional steering
    turn = max(-1.0, min(1.0, ang / 40.0))

    left = base - 0.5 * turn
    right = base + 0.5 * turn
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


def weapons(me, enemy, arena):
    wpn = me.weapons.get('front')
    if not wpn or wpn['type'] != 'flipper':
        return None

    # Only fire when flipper is ready and we have shots left
    if not wpn.get('ready', False):
        return None

    dist = distance_to(enemy.x, enemy.y)

    # Fire when enemy is close and appears to be at rest on the floor
    enemy_resting = (enemy.z <= 0.02) and (enemy.speed < 0.3) and (not enemy.airborne)
    if dist < 1.1 and enemy_resting:
        return flip('front')

    return None

